// The weather map: a tileable 2D field over WEATHER_TILE km that says where clouds may form and
// what kind, regenerated by compute whenever the weather changes and scrolled by the wind aloft.
//   r: coverage 0..1 (the Nubis coverage remap threshold)
//   g: type 0..1, blending the layer's profile A (0) toward profile B (1) — e.g. cumulus → congestus;
//      smooth across a cell (cloudTypes.cellType), so a heap's depth doesn't peak at its centre
//   b: precipitation under the cell (rain shafts, darker bases)
//   a: column height scale, 0..1 of MAX_COLUMN_SCALE × the profile's thickness: a dome over each
//      cell (cloudTypes.cellDome / columnScale)
// Cells come from Worley noise (cumulus heaps, storm cells), sheets from Perlin FBM; a third,
// very-low-frequency FBM clusters them so the sky isn't uniformly speckled. While one cloud type
// morphs into another the cell field crossfades between the two types' cell layouts.

import {
  type ComputeNode,
  LinearFilter,
  RepeatWrapping,
  RGBAFormat,
  StorageTexture,
  UnsignedByteType,
  type WebGPURenderer,
} from 'three/webgpu';

import { type N, tsl } from '../tsl';
import { CELL_PEAK, DOME_RIM, MAX_COLUMN_SCALE, type WeatherMapParams } from './cloudTypes';
import { perlinFbm, worley3 } from './noiseNodes';

const { Fn, float, instanceIndex, max, mix, saturate, smoothstep, sqrt, textureStore, uint, uniform, uvec2 } =
  tsl;
const { vec2, vec3, vec4 } = tsl;

const sameParams = (a: WeatherMapParams, b: WeatherMapParams): boolean =>
  (Object.keys(a) as (keyof WeatherMapParams)[]).every((key) => a[key] === b[key]);

const WEATHER_SIZE = 512;
export const WEATHER_TILE = 72; // km

export class WeatherMap {
  readonly texture: StorageTexture;
  private kernel: ComputeNode;
  private dirty = true;
  private params: WeatherMapParams | null = null;
  private readonly u = {
    cells: uniform(20),
    cellsTo: uniform(20),
    cellsMix: uniform(0),
    cellWeight: uniform(0.7),
    threshold: uniform(0.6),
    softness: uniform(0.12),
    deck: uniform(0),
    typeBias: uniform(0),
    typeSpread: uniform(1),
    precipitation: uniform(0),
  };

  constructor() {
    const t = new StorageTexture(WEATHER_SIZE, WEATHER_SIZE);
    t.type = UnsignedByteType;
    t.format = RGBAFormat;
    t.magFilter = LinearFilter;
    t.minFilter = LinearFilter;
    t.wrapS = t.wrapT = RepeatWrapping;
    t.generateMipmaps = false;
    t.name = 'clouds-weather-map';
    this.texture = t;
    this.kernel = this.build();
  }

  // Returns whether the map will regenerate (the parameters changed).
  set(params: WeatherMapParams): boolean {
    if (this.params && sameParams(this.params, params)) return false;
    this.params = { ...params };
    const u = this.u;
    u.cells.value = Math.max(1, Math.round(params.cellsPerTile));
    u.cellsTo.value = Math.max(1, Math.round(params.cellsPerTileTo));
    u.cellsMix.value = Math.min(1, Math.max(0, params.cellsMix));
    u.cellWeight.value = params.cellWeight;
    u.threshold.value = params.threshold;
    u.softness.value = Math.max(0.01, params.softness);
    u.deck.value = params.deck;
    u.typeBias.value = params.typeBias;
    u.typeSpread.value = params.typeSpread;
    u.precipitation.value = params.precipitation;
    this.dirty = true;
    return true;
  }

  // Regenerates the map if the parameters changed.
  update(renderer: WebGPURenderer): boolean {
    if (!this.dirty) return false;
    void renderer.compute(this.kernel);
    this.dirty = false;
    return true;
  }

  dispose(): void {
    this.kernel.dispose();
    this.texture.dispose();
  }

  private build(): ComputeNode {
    const n = WEATHER_SIZE;
    const u = this.u;
    const kernel = Fn(() => {
      const x = instanceIndex.mod(uint(n));
      const y = instanceIndex.div(uint(n));
      const uv = vec2(float(x), float(y)).add(0.5).div(n).toVar();
      const p = vec3(uv, 0.5).toVar();
      const sheets = perlinFbm(p, vec3(5, 5, 1), 4, 101).toVar();
      const cluster = perlinFbm(p, vec3(2, 2, 1), 3, 111).toVar();
      const cellsAt = (scale: N, seed: number): N => {
        const q = vec3(uv.mul(scale), 0.5);
        return float(1).sub(sqrt(worley3(q, vec3(scale, scale, 64), seed)));
      };
      // Two octaves of cells: big heaps plus smaller ones in between (for both layouts of a morph).
      const heapsAt = (cells: N): N =>
        cellsAt(cells, 121)
          .mul(0.75)
          .add(cellsAt(cells.mul(2), 131).mul(0.25));
      const heaps = mix(heapsAt(u.cells), heapsAt(u.cellsTo), u.cellsMix).toVar();
      const shaped = mix(sheets, heaps.mul(sheets.mul(0.5).add(0.75)), u.cellWeight);
      const local = shaped.mul(mix(0.7, 1.25, cluster)).toVar();
      const cover = max(
        smoothstep(u.threshold.sub(u.softness), u.threshold.add(u.softness), local),
        u.deck.mul(sheets.mul(0.4).add(0.6)),
      ).toVar();
      // Cells grow toward profile B where a cell centred here would be strong (cloudTypes.cellType):
      // the regional fields, not this cell's radial falloff (which would make every heap a cone).
      const cellPeak = mix(sheets, sheets.mul(0.5).add(0.75).mul(CELL_PEAK), u.cellWeight);
      const strength = cellPeak
        .mul(mix(0.7, 1.25, cluster))
        .sub(u.threshold)
        .div(max(float(1).sub(u.threshold), 0.05));
      const type = saturate(u.typeBias.add(strength.mul(u.typeSpread)).add(sheets.sub(0.5).mul(0.3))).toVar();
      // Dome over each cell (cloudTypes.cellDome): rim/saddles 0 → well-grown centres 1.
      const arc = (q: N): N => sqrt(q.mul(q.oneMinus().add(1)));
      const grown = saturate(local.sub(u.threshold).add(u.softness).div(u.softness.mul(4)));
      const central = saturate(heaps.sub(0.4).div(0.5));
      const dome = arc(grown).mul(arc(central)).toVar();
      // Rain falls under the grown cores.
      const rain = u.precipitation.mul(cover).mul(mix(smoothstep(0.35, 0.85, type).mul(dome), 1, u.deck));
      // Column height (cloudTypes.columnScale): smooth noise × the dome, level for sheets.
      const shape = mix(1, dome.mul(1 - DOME_RIM).add(DOME_RIM), u.cellWeight);
      const height = mix(0.7, 1.3, perlinFbm(p, vec3(9, 9, 1), 2, 141))
        .mul(shape)
        .div(MAX_COLUMN_SCALE);
      textureStore(this.texture, uvec2(x, y), vec4(cover, type, saturate(rain), height)).toWriteOnly();
    });
    const node: ComputeNode = kernel().compute(n * n, [64]);
    node.setName('clouds-weather-map');
    return node;
  }
}
